function scoreOfString(s) {
  let score = 0;
  for (let i = 1; i < s.length; i++) {
    const previous = s.charCodeAt(i - 1);
    const current = s.charCodeAt(i);
    score += Math.abs(current - previous);
  }
  return score;
}

