function scoreOfString(s) {
  const alphabet = 'abcdefghijklmnopqrstuvwxyz';
  const positions = s.split('').map(ch => alphabet.indexOf(ch));
  let total = 0;
  positions.forEach((pos, index) => {
    if (index === 0) return;
    const other = positions[index - 1];
    total += Math.max(pos, other) - Math.min(pos, other);
  });
  return total;
}

