function generate(rand, size) {
  const length = size === 'large' ? 100 : 2 + Math.floor(rand() * 8);
  const span = size === 'large' || rand() < 0.6 ? 26 : 1 + Math.floor(rand() * 3);
  const start = Math.floor(rand() * (27 - span));
  let s = '';
  for (let i = 0; i < length; i++) s += String.fromCharCode(97 + start + Math.floor(rand() * span));
  return [s];
}
